-- Passo 20.3: canonical methodology knowledge base. Rollback: archive the release,
-- then drop methodology_* objects only after reverting runtime to the versioned snapshot.
create table if not exists public.methodology_releases (
  id uuid primary key default gen_random_uuid(), version text not null unique,
  status text not null check(status in ('draft','active','archived')),
  content_sha256 text not null check(content_sha256 ~ '^[a-f0-9]{64}$'), payload jsonb not null,
  published_at timestamptz not null default now(), notes text not null
);
create unique index if not exists one_active_methodology_release on public.methodology_releases(status) where status='active';
create table if not exists public.methodology_sources (
  source_id text primary key, source_type text not null, organization text not null, title text not null,
  canonical_url text not null, retrieved_at timestamptz not null, updated_at timestamptz not null,
  authority text not null, status text not null, notes text
);
create table if not exists public.methodology_targets (
  slug text primary key, parent_slug text references public.methodology_targets(slug) deferrable initially deferred,
  family text not null, model text, version text, platform text, level text not null check(level in ('general','family','model','version')),
  display_name text not null, is_public boolean not null default true
);
create table if not exists public.methodology_rules (
  rule_id text primary key, rule_text text not null, rule_type text not null,
  provenance text not null check(provenance in ('VERIFIED_OFFICIAL','VERIFIED_EMPIRICAL','PROJECT_HEURISTIC','UNVERIFIED','DEPRECATED','CONFLICTING')),
  confidence text not null, source_id text references public.methodology_sources(source_id), evidence_reference text,
  conflict_group text, supersedes text references public.methodology_rules(rule_id) deferrable initially deferred,
  priority smallint not null check(priority between 1 and 999), is_active boolean not null, notes text
);
create table if not exists public.methodology_rule_applicability (
  rule_id text references public.methodology_rules(rule_id) on delete cascade,
  target_slug text references public.methodology_targets(slug) on delete cascade,
  task_type text not null, platform text not null default '', inheritance_level text not null,
  primary key(rule_id,target_slug,task_type,platform)
);
create table if not exists public.methodology_examples (
  example_id text primary key, target_slug text references public.methodology_targets(slug), task_type text not null,
  structure_reference text not null, source_id text references public.methodology_sources(source_id),
  provenance text not null, is_active boolean not null, notes text
);

alter table public.methodology_releases enable row level security;
alter table public.methodology_sources enable row level security;
alter table public.methodology_targets enable row level security;
alter table public.methodology_rules enable row level security;
alter table public.methodology_rule_applicability enable row level security;
alter table public.methodology_examples enable row level security;
revoke all on public.methodology_releases,public.methodology_sources,public.methodology_targets,public.methodology_rules,public.methodology_rule_applicability,public.methodology_examples from anon,authenticated;
grant select on public.methodology_releases,public.methodology_sources,public.methodology_targets,public.methodology_rules,public.methodology_rule_applicability,public.methodology_examples to anon,authenticated;
drop policy if exists "read active methodology release" on public.methodology_releases;
create policy "read active methodology release" on public.methodology_releases for select to anon,authenticated using(status='active');

