do $$ declare p jsonb := (select payload from public.methodology_releases where version='2.0.0'); t jsonb; r jsonb; e jsonb; tasks jsonb; task text; begin
  for t in select * from jsonb_array_elements(p->'sources') loop
    insert into public.methodology_sources values(t->>'id',t->>'sourceType',t->>'organization',t->>'title',t->>'canonicalUrl',(t->>'retrievedAt')::timestamptz,(t->>'updatedAt')::timestamptz,t->>'authority',t->>'status',t->>'notes') on conflict(source_id) do update set updated_at=excluded.updated_at,status=excluded.status,notes=excluded.notes;
  end loop;
  set constraints all deferred;
  insert into public.methodology_targets(slug,parent_slug,family,level,display_name,is_public) values('general',null,'general','general','General',false) on conflict(slug) do nothing;
  for t in select * from jsonb_array_elements((p->'targets')||(p->'specificTargets')) loop
    insert into public.methodology_targets(slug,parent_slug,family,model,version,platform,level,display_name,is_public) values(t->>'slug',null,coalesce(t->>'parentSlug',t->>'slug'),case when t->>'level'='model' then t->>'slug' end,case when t->>'level'='version' then t->>'slug' end,null,coalesce(t->>'level','family'),t->>'displayName',coalesce((t->>'public')::boolean,true)) on conflict(slug) do nothing;
  end loop;
  for t in select * from jsonb_array_elements(p->'specificTargets') loop update public.methodology_targets set parent_slug=t->>'parentSlug' where slug=t->>'slug'; end loop;
  for r in select * from jsonb_array_elements((p->'generalRules') || (select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(p->'targets') a cross join lateral jsonb_array_elements(a->'rules') x)) loop
    insert into public.methodology_rules(rule_id,rule_text,rule_type,provenance,confidence,source_id,evidence_reference,conflict_group,supersedes,priority,is_active,notes) values(r->>'id',r->>'text',r->>'ruleType',r->>'status',r->>'confidence',r->>'sourceId',r->>'evidenceReference',r->>'conflictGroup',r->>'supersedes',(r->>'priority')::smallint,(r->>'active')::boolean,r->>'notes') on conflict(rule_id) do update set rule_text=excluded.rule_text,provenance=excluded.provenance,is_active=excluded.is_active;
  end loop;
  for t in select * from jsonb_array_elements(p->'targets') loop for r in select * from jsonb_array_elements(t->'rules') loop tasks:=coalesce(r->'taskTypes','["cited"]'); for task in select jsonb_array_elements_text(tasks) loop insert into public.methodology_rule_applicability values(r->>'id',t->>'slug',task,'','family') on conflict do nothing; end loop; end loop; end loop;
  for r in select * from jsonb_array_elements(p->'generalRules') loop tasks:=r->'taskTypes'; for task in select jsonb_array_elements_text(tasks) loop insert into public.methodology_rule_applicability values(r->>'id','general',task,'','general') on conflict do nothing; end loop; end loop;
  for e in select * from jsonb_array_elements(p->'examples') loop insert into public.methodology_examples values(e->>'id',e->>'target',e->>'taskType','objective/context/delivery/acceptance-criteria',e->>'sourceId',e->>'status',(e->>'active')::boolean,'Content remains in signed release; runtime exposes structure only') on conflict(example_id) do nothing; end loop;
end $$;

-- Public normalized metadata is limited to the active, allowed runtime knowledge.
create policy "read methodology sources" on public.methodology_sources for select to anon,authenticated using(status in ('VERIFIED_OFFICIAL','VERIFIED_EMPIRICAL'));
create policy "read methodology targets" on public.methodology_targets for select to anon,authenticated using(true);
create policy "read verified methodology rules" on public.methodology_rules for select to anon,authenticated using(is_active and provenance in ('VERIFIED_OFFICIAL','VERIFIED_EMPIRICAL'));
create policy "read methodology applicability" on public.methodology_rule_applicability for select to anon,authenticated using(exists(select 1 from public.methodology_rules r where r.rule_id=methodology_rule_applicability.rule_id and r.is_active and r.provenance in ('VERIFIED_OFFICIAL','VERIFIED_EMPIRICAL')));
create policy "read verified methodology examples" on public.methodology_examples for select to anon,authenticated using(is_active and provenance in ('VERIFIED_OFFICIAL','VERIFIED_EMPIRICAL'));
